ok = 0; cm = ru = di = 0
for cid in P:
    with open(os.path.join(base, cid + ".json"), encoding="utf-8") as f:
        o = json.load(f)
    assert o["case_id"] == cid and set(o) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
    assert isinstance(o["prediction_text"], str) and len(o["prediction_text"]) > 30, cid
    assert isinstance(o["basis"], str) and o["basis"].startswith("tradition/system:"), cid
    assert 0 <= o["confidence"] <= 1, cid
    t = o["trigger"]; assert set(t) == {"changed_main","reserve_used","disputed","reason"}, cid
    assert all(isinstance(t[k], bool) for k in ("changed_main","reserve_used","disputed")) and isinstance(t["reason"], str), cid
    cm += t["changed_main"]; ru += t["reserve_used"]; di += t["disputed"]; ok += 1
